questionvariables.text:
/* A is m x n, x is p x 1. Defined iff n = p. */
m : rand(2) + 2;                         /* rows of A: 2 or 3 */
n : rand(2) + 2;                         /* cols of A: 2 or 3 */
defcase : rand([true, true, false]);     /* ~2/3 of variants are defined */
p : if defcase then n else 5 - n;        /* p = n (defined) or the other of 2/3 */

MM  : genmatrix(lambda([i,j], rand(13) - 6), m, n);   /* entries -6..6 */
vv0 : genmatrix(lambda([i,j], rand_with_prohib(-6, 6, [0])), p, 1);

/* Guard: if a defined product would be the zero vector, nudge x so 'defined' is non-zero */
vv : if defcase then (if zeromatrixp(MM . vv0) then vv0 + genmatrix(lambda([i,j], 1), p, 1) else vv0) else vv0;

ta   : if defcase then MM . vv else zeromatrix(m, 1);   /* model answer */
ddef : if defcase then 1 else 0;                        /* numeric flag for PRT/feedback */

/* Diagnostic helper guaranteed distinct from ta on every variant */
onescol   : genmatrix(lambda([i,j], 1), m, 1);
wrongprod : ta + onescol;

/* Build clean LaTeX dot-product expansion inside the result vector */
join_plus(L) := apply(sconcat, rest(apply(append, makelist([" + ", x], x, L))));
join_nl(L)   := apply(sconcat, rest(apply(append, makelist([" \\\\ ", x], x, L))));
fmt_term(a, b) := sconcat(if is(a < 0) then sconcat("(", a, ")") else string(a), "(", b, ")");
row_dot(i)   := join_plus(makelist(fmt_term(MM[i,j], vv[j,1]), j, 1, n));
prod_tex     : if defcase then sconcat("\\begin{bmatrix} ", join_nl(makelist(row_dot(i), i, 1, m)), " \\end{bmatrix}") else "";
